            function renderKilkayaSlot(slotData) {
              const id = slotData.elementId || slotData.placementId;
              const t = document.getElementById(id);

              if (t) {
                if (slotData.data.title) {
                  const titles = t.getElementsByClassName("teaser-title");
                  const exclusives = t.getElementsByClassName("teaser-kicker");

                  if (titles.length) {
                    Array.from(titles).forEach((title) => {
                      title.textContent = slotData.data.title;
                    });
                  }

                  if (exclusives.length) {
                    Array.from(exclusives).forEach((excl) => {
                      excl.textContent = slotData.data.exclusive;
                    });
                  }
                }

                t.setAttribute('data-k5a-nisa', slotData.testId);
              }
            }
